SET ROLE talus_fn;
CREATE TABLE app.tenant_booking_policy (tenant_id uuid NOT NULL, tenant_booking_policy_id uuid NOT NULL, version_number integer NOT NULL CHECK(version_number>0), timezone_name text NOT NULL, booking_window_days integer NOT NULL CHECK(booking_window_days>0), minimum_advance_minutes integer NOT NULL CHECK(minimum_advance_minutes>=0), assignment_lead_minutes integer NOT NULL CHECK(assignment_lead_minutes>=0), calendar_day_convention text NOT NULL CHECK(calendar_day_convention IN ('pickup_date_inclusive','return_date_inclusive')), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(tenant_id,tenant_booking_policy_id), UNIQUE(tenant_id,version_number), FOREIGN KEY(tenant_id) REFERENCES app.tenant(tenant_id));
CREATE TABLE app.tenant_waiver_policy (tenant_id uuid NOT NULL, tenant_waiver_policy_id uuid NOT NULL, version_number integer NOT NULL CHECK(version_number>0), signing_mode text NOT NULL CHECK(signing_mode IN ('individual','booking_scope')), required_fields jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(required_fields)='object'), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(tenant_id,tenant_waiver_policy_id), UNIQUE(tenant_id,version_number), FOREIGN KEY(tenant_id) REFERENCES app.tenant(tenant_id));
CREATE TABLE app.tenant_inspection_policy (tenant_id uuid NOT NULL, tenant_inspection_policy_id uuid NOT NULL, version_number integer NOT NULL CHECK(version_number>0), pre_checkout_required boolean NOT NULL, post_return_required boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(tenant_id,tenant_inspection_policy_id), UNIQUE(tenant_id,version_number), FOREIGN KEY(tenant_id) REFERENCES app.tenant(tenant_id));
CREATE TABLE app.tenant_pricing_policy (tenant_id uuid NOT NULL, tenant_pricing_policy_id uuid NOT NULL, version_number integer NOT NULL CHECK(version_number>0), multi_day_discount_basis_points app.basis_points NOT NULL, rounding_rule_version text NOT NULL, allocation_rule_version text NOT NULL, tax_mode text NOT NULL CHECK(tax_mode IN ('unconfigured','external_adapter','fixed_rules')), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(tenant_id,tenant_pricing_policy_id), UNIQUE(tenant_id,version_number), FOREIGN KEY(tenant_id) REFERENCES app.tenant(tenant_id));
CREATE TABLE app.tenant_payment_policy (tenant_id uuid NOT NULL, tenant_payment_policy_id uuid NOT NULL, version_number integer NOT NULL CHECK(version_number>0), payment_timing text NOT NULL CHECK(payment_timing IN ('pay_in_full','split_deposit')), platform_fee_mode text NOT NULL CHECK(platform_fee_mode IN ('unconfigured','flat_cents','basis_points')), cancellation_terms jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(cancellation_terms)='object'), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(tenant_id,tenant_payment_policy_id), UNIQUE(tenant_id,version_number), FOREIGN KEY(tenant_id) REFERENCES app.tenant(tenant_id));
CREATE TABLE app.tenant_telemetry_policy (tenant_id uuid NOT NULL, tenant_telemetry_policy_id uuid NOT NULL, version_number integer NOT NULL CHECK(version_number>0), raw_retention_days integer NOT NULL CHECK(raw_retention_days>0), freshness_threshold_seconds integer NOT NULL CHECK(freshness_threshold_seconds>0), clock_tolerance_seconds integer NOT NULL CHECK(clock_tolerance_seconds>=0), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(tenant_id,tenant_telemetry_policy_id), UNIQUE(tenant_id,version_number), FOREIGN KEY(tenant_id) REFERENCES app.tenant(tenant_id));
CREATE TABLE app.tenant_sms_config (tenant_id uuid NOT NULL, tenant_sms_config_id uuid NOT NULL, version_number integer NOT NULL CHECK(version_number>0), enabled boolean NOT NULL, sender_reference text NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(tenant_id,tenant_sms_config_id), UNIQUE(tenant_id,version_number), FOREIGN KEY(tenant_id) REFERENCES app.tenant(tenant_id));
CREATE TABLE app.tenant_configuration_version (tenant_id uuid NOT NULL, tenant_configuration_version_id uuid NOT NULL UNIQUE, version_number integer NOT NULL CHECK(version_number>0), tenant_booking_policy_id uuid NOT NULL, tenant_waiver_policy_id uuid NOT NULL, tenant_inspection_policy_id uuid NOT NULL, tenant_pricing_policy_id uuid NOT NULL, tenant_payment_policy_id uuid NOT NULL, tenant_telemetry_policy_id uuid NOT NULL, tenant_sms_config_id uuid NOT NULL, published_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(tenant_id,tenant_configuration_version_id), UNIQUE(tenant_id,version_number), FOREIGN KEY(tenant_id) REFERENCES app.tenant(tenant_id), FOREIGN KEY(tenant_id,tenant_booking_policy_id) REFERENCES app.tenant_booking_policy(tenant_id,tenant_booking_policy_id), FOREIGN KEY(tenant_id,tenant_waiver_policy_id) REFERENCES app.tenant_waiver_policy(tenant_id,tenant_waiver_policy_id), FOREIGN KEY(tenant_id,tenant_inspection_policy_id) REFERENCES app.tenant_inspection_policy(tenant_id,tenant_inspection_policy_id), FOREIGN KEY(tenant_id,tenant_pricing_policy_id) REFERENCES app.tenant_pricing_policy(tenant_id,tenant_pricing_policy_id), FOREIGN KEY(tenant_id,tenant_payment_policy_id) REFERENCES app.tenant_payment_policy(tenant_id,tenant_payment_policy_id), FOREIGN KEY(tenant_id,tenant_telemetry_policy_id) REFERENCES app.tenant_telemetry_policy(tenant_id,tenant_telemetry_policy_id), FOREIGN KEY(tenant_id,tenant_sms_config_id) REFERENCES app.tenant_sms_config(tenant_id,tenant_sms_config_id));
CREATE TABLE app.tenant_current_configuration (tenant_id uuid PRIMARY KEY, tenant_configuration_version_id uuid NOT NULL, updated_at timestamptz NOT NULL DEFAULT clock_timestamp(), FOREIGN KEY(tenant_id,tenant_configuration_version_id) REFERENCES app.tenant_configuration_version(tenant_id,tenant_configuration_version_id));
ALTER TABLE app.booking_terms_revision ADD COLUMN tenant_configuration_version_id uuid REFERENCES app.tenant_configuration_version(tenant_configuration_version_id);
CREATE TABLE app.rental_product (tenant_id uuid NOT NULL, rental_product_id uuid NOT NULL, category_location_id uuid NOT NULL, product_code text NOT NULL, display_name text NOT NULL, description text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, visible boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(tenant_id,rental_product_id), UNIQUE(tenant_id,product_code), FOREIGN KEY(tenant_id,category_location_id) REFERENCES app.category_location(tenant_id,category_location_id));
CREATE TABLE app.product_rate (tenant_id uuid NOT NULL, product_rate_id uuid NOT NULL, rental_product_id uuid NOT NULL, version_number integer NOT NULL CHECK(version_number>0), effective_at timestamptz NOT NULL, daily_rate_cents app.cents NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(tenant_id,product_rate_id), UNIQUE(tenant_id,rental_product_id,version_number), UNIQUE(tenant_id,rental_product_id,effective_at), FOREIGN KEY(tenant_id,rental_product_id) REFERENCES app.rental_product(tenant_id,rental_product_id));
CREATE TABLE app.multi_day_discount_tier (tenant_id uuid NOT NULL, multi_day_discount_tier_id uuid NOT NULL, rental_product_id uuid NOT NULL, minimum_day_count integer NOT NULL CHECK(minimum_day_count>=2), discount_basis_points app.basis_points NOT NULL, PRIMARY KEY(tenant_id,multi_day_discount_tier_id), UNIQUE(tenant_id,rental_product_id,minimum_day_count), FOREIGN KEY(tenant_id,rental_product_id) REFERENCES app.rental_product(tenant_id,rental_product_id));
CREATE TABLE app.addon (tenant_id uuid NOT NULL, addon_id uuid NOT NULL, addon_code text NOT NULL, display_name text NOT NULL, description text NOT NULL DEFAULT '', charging_basis text NOT NULL CHECK(charging_basis IN ('per_booking','per_unit','per_unit_day')), active boolean NOT NULL DEFAULT true, visible boolean NOT NULL DEFAULT true, PRIMARY KEY(tenant_id,addon_id), UNIQUE(tenant_id,addon_code), FOREIGN KEY(tenant_id) REFERENCES app.tenant(tenant_id));
CREATE TABLE app.booking_rule (tenant_id uuid NOT NULL, booking_rule_id uuid NOT NULL, rental_product_id uuid, rule_code text NOT NULL, rule_value jsonb NOT NULL CHECK(jsonb_typeof(rule_value)='object'), active boolean NOT NULL DEFAULT true, PRIMARY KEY(tenant_id,booking_rule_id), UNIQUE(tenant_id,rental_product_id,rule_code), FOREIGN KEY(tenant_id,rental_product_id) REFERENCES app.rental_product(tenant_id,rental_product_id));
ALTER TABLE app.booking_item_terms_revision ADD COLUMN product_rate_id uuid;
ALTER TABLE app.booking_item_terms_revision ADD CONSTRAINT bitr_product_rate_fk FOREIGN KEY(tenant_id,product_rate_id) REFERENCES app.product_rate(tenant_id,product_rate_id);
ALTER TABLE app.machine ADD COLUMN fleet_number text;
ALTER TABLE app.machine DROP CONSTRAINT machine_operational_state_check;
ALTER TABLE app.machine ADD CONSTRAINT machine_operational_state_check CHECK(operational_state IN ('in_service','maintenance','offline','retired'));
CREATE UNIQUE INDEX machine_fleet_number_uq ON app.machine(tenant_id,lower(fleet_number)) WHERE fleet_number IS NOT NULL;
CREATE TABLE app.machine_state_change (tenant_id uuid NOT NULL, machine_state_change_id uuid NOT NULL, machine_id uuid NOT NULL, previous_operational_state text NOT NULL, new_operational_state text NOT NULL, reason text NOT NULL, effective_at timestamptz NOT NULL DEFAULT clock_timestamp(), actor_principal_id uuid NOT NULL, PRIMARY KEY(tenant_id,machine_state_change_id), FOREIGN KEY(tenant_id,machine_id) REFERENCES app.machine(tenant_id,machine_id), FOREIGN KEY(tenant_id,actor_principal_id) REFERENCES app.principal(tenant_id,principal_id));
CREATE TABLE app.machine_transfer (tenant_id uuid NOT NULL, machine_transfer_id uuid NOT NULL, machine_id uuid NOT NULL, from_category_location_id uuid NOT NULL, to_category_location_id uuid NOT NULL, state text NOT NULL CHECK(state IN ('in_transit','completed','cancelled')), initiated_at timestamptz NOT NULL DEFAULT clock_timestamp(), planned_arrival_at timestamptz NOT NULL, completed_at timestamptz, reason text NOT NULL, initiated_by_principal_id uuid NOT NULL, completed_by_principal_id uuid, PRIMARY KEY(tenant_id,machine_transfer_id), FOREIGN KEY(tenant_id,machine_id) REFERENCES app.machine(tenant_id,machine_id), FOREIGN KEY(tenant_id,from_category_location_id) REFERENCES app.category_location(tenant_id,category_location_id), FOREIGN KEY(tenant_id,to_category_location_id) REFERENCES app.category_location(tenant_id,category_location_id), FOREIGN KEY(tenant_id,initiated_by_principal_id) REFERENCES app.principal(tenant_id,principal_id), CHECK(planned_arrival_at>initiated_at));
CREATE UNIQUE INDEX machine_active_transfer_uq ON app.machine_transfer(tenant_id,machine_id) WHERE state='in_transit';
ALTER TABLE app.machine_occupancy ADD COLUMN machine_transfer_id uuid;
ALTER TABLE app.machine_occupancy ADD CONSTRAINT mo_transfer_fk FOREIGN KEY(tenant_id,machine_transfer_id) REFERENCES app.machine_transfer(tenant_id,machine_transfer_id);
ALTER TABLE app.machine_occupancy DROP CONSTRAINT machine_occupancy_occupancy_kind_check;
ALTER TABLE app.machine_occupancy ADD CONSTRAINT machine_occupancy_occupancy_kind_check CHECK(occupancy_kind IN ('rental','maintenance','transfer'));
ALTER TABLE app.machine_occupancy DROP CONSTRAINT machine_occupancy_check;
ALTER TABLE app.machine_occupancy ADD CONSTRAINT machine_occupancy_check CHECK((occupancy_kind='rental' AND booking_item_id IS NOT NULL AND booking_item_terms_revision_id IS NOT NULL AND maintenance_reference_id IS NULL AND machine_transfer_id IS NULL) OR (occupancy_kind='maintenance' AND booking_item_id IS NULL AND booking_item_terms_revision_id IS NULL AND maintenance_reference_id IS NOT NULL AND machine_transfer_id IS NULL) OR (occupancy_kind='transfer' AND booking_item_id IS NULL AND booking_item_terms_revision_id IS NULL AND maintenance_reference_id IS NULL AND machine_transfer_id IS NOT NULL));
CREATE TABLE app.device_model (tenant_id uuid NOT NULL, device_model_id uuid NOT NULL, manufacturer text NOT NULL, model_code text NOT NULL, active boolean NOT NULL DEFAULT true, PRIMARY KEY(tenant_id,device_model_id), UNIQUE(tenant_id,manufacturer,model_code), FOREIGN KEY(tenant_id) REFERENCES app.tenant(tenant_id));
CREATE TABLE app.device (tenant_id uuid NOT NULL, device_id uuid NOT NULL, device_model_id uuid NOT NULL, hardware_serial text NOT NULL, active boolean NOT NULL DEFAULT true, retired_at timestamptz, PRIMARY KEY(tenant_id,device_id), UNIQUE(tenant_id,hardware_serial), FOREIGN KEY(tenant_id,device_model_id) REFERENCES app.device_model(tenant_id,device_model_id));
CREATE TABLE app.device_capability (tenant_id uuid NOT NULL, device_model_id uuid NOT NULL, capability_code text NOT NULL, PRIMARY KEY(tenant_id,device_model_id,capability_code), FOREIGN KEY(tenant_id,device_model_id) REFERENCES app.device_model(tenant_id,device_model_id));
CREATE TABLE app.device_installation (tenant_id uuid NOT NULL, device_installation_id uuid NOT NULL, device_id uuid NOT NULL, machine_id uuid NOT NULL, installed_at timestamptz NOT NULL, removed_at timestamptz, bound_by_principal_id uuid NOT NULL, PRIMARY KEY(tenant_id,device_installation_id), FOREIGN KEY(tenant_id,device_id) REFERENCES app.device(tenant_id,device_id), FOREIGN KEY(tenant_id,machine_id) REFERENCES app.machine(tenant_id,machine_id), FOREIGN KEY(tenant_id,bound_by_principal_id) REFERENCES app.principal(tenant_id,principal_id), CHECK(removed_at IS NULL OR removed_at>installed_at));
ALTER TABLE app.device_installation ADD CONSTRAINT device_installation_device_overlap EXCLUDE USING gist(tenant_id WITH =,device_id WITH =,tstzrange(installed_at,COALESCE(removed_at,'infinity'::timestamptz),'[)') WITH &&);
CREATE TABLE app.geofence (tenant_id uuid NOT NULL, geofence_id uuid NOT NULL, display_name text NOT NULL, geometry jsonb NOT NULL CHECK(jsonb_typeof(geometry)='object'), active boolean NOT NULL DEFAULT true, PRIMARY KEY(tenant_id,geofence_id), UNIQUE(tenant_id,display_name), FOREIGN KEY(tenant_id) REFERENCES app.tenant(tenant_id));
CREATE TABLE app.operating_limit (tenant_id uuid NOT NULL, operating_limit_id uuid NOT NULL, category_location_id uuid NOT NULL, geofence_id uuid, limit_kind text NOT NULL CHECK(limit_kind IN ('speed','engine_rpm','distance_from_origin')), limit_value bigint NOT NULL CHECK(limit_value>=0), unit_code text NOT NULL CHECK(unit_code IN ('kph','rpm','meters')), version_number integer NOT NULL CHECK(version_number>0), active boolean NOT NULL DEFAULT true, PRIMARY KEY(tenant_id,operating_limit_id), FOREIGN KEY(tenant_id,category_location_id) REFERENCES app.category_location(tenant_id,category_location_id), FOREIGN KEY(tenant_id,geofence_id) REFERENCES app.geofence(tenant_id,geofence_id));
ALTER TABLE app.trip ADD COLUMN tenant_configuration_version_id uuid;
ALTER TABLE app.trip ADD COLUMN product_rate_id uuid;
CREATE OR REPLACE FUNCTION app.m03_immutable() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER AS $$ BEGIN RAISE EXCEPTION 'IMMUTABLE_VERSION_MUTATION_FORBIDDEN' USING ERRCODE='P0001'; END; $$;
CREATE OR REPLACE FUNCTION app.m03_snapshot_trip() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=app,pg_catalog AS $$ BEGIN SELECT bt.tenant_configuration_version_id,it.product_rate_id INTO NEW.tenant_configuration_version_id,NEW.product_rate_id FROM app.booking_item_terms_revision it JOIN app.booking_terms_revision bt ON bt.tenant_id=it.tenant_id AND bt.booking_terms_revision_id=it.booking_terms_revision_id JOIN app.booking_item bi ON bi.tenant_id=it.tenant_id AND bi.booking_item_id=it.booking_item_id WHERE it.tenant_id=NEW.tenant_id AND it.booking_item_id=NEW.booking_item_id AND it.booking_item_terms_revision_id=bi.current_terms_revision_id; RETURN NEW; END; $$;
CREATE TRIGGER m03_trip_snapshot BEFORE INSERT ON app.trip FOR EACH ROW EXECUTE FUNCTION app.m03_snapshot_trip();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['tenant_booking_policy','tenant_waiver_policy','tenant_inspection_policy','tenant_pricing_policy','tenant_payment_policy','tenant_telemetry_policy','tenant_sms_config','tenant_configuration_version','rental_product','product_rate'] LOOP EXECUTE format('CREATE TRIGGER m03_%I_immutable BEFORE UPDATE OR DELETE ON app.%I FOR EACH ROW EXECUTE FUNCTION app.m03_immutable()',t,t); END LOOP; END; $$;
CREATE OR REPLACE FUNCTION app.publish_configuration_version(p_id uuid,p_version integer,p_booking uuid,p_waiver uuid,p_inspection uuid,p_pricing uuid,p_payment uuid,p_telemetry uuid,p_sms uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id(); BEGIN PERFORM app.require_staff_role('manager'); IF NOT EXISTS(SELECT 1 FROM app.tenant_booking_policy x WHERE x.tenant_id=t AND x.tenant_booking_policy_id=p_booking) OR NOT EXISTS(SELECT 1 FROM app.tenant_waiver_policy x WHERE x.tenant_id=t AND x.tenant_waiver_policy_id=p_waiver) OR NOT EXISTS(SELECT 1 FROM app.tenant_inspection_policy x WHERE x.tenant_id=t AND x.tenant_inspection_policy_id=p_inspection) OR NOT EXISTS(SELECT 1 FROM app.tenant_pricing_policy x WHERE x.tenant_id=t AND x.tenant_pricing_policy_id=p_pricing) OR NOT EXISTS(SELECT 1 FROM app.tenant_payment_policy x WHERE x.tenant_id=t AND x.tenant_payment_policy_id=p_payment) OR NOT EXISTS(SELECT 1 FROM app.tenant_telemetry_policy x WHERE x.tenant_id=t AND x.tenant_telemetry_policy_id=p_telemetry) OR NOT EXISTS(SELECT 1 FROM app.tenant_sms_config x WHERE x.tenant_id=t AND x.tenant_sms_config_id=p_sms) THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND' USING ERRCODE='P0001'; END IF; INSERT INTO app.tenant_configuration_version VALUES(t,p_id,p_version,p_booking,p_waiver,p_inspection,p_pricing,p_payment,p_telemetry,p_sms,clock_timestamp()); INSERT INTO app.tenant_current_configuration VALUES(t,p_id,clock_timestamp()) ON CONFLICT(tenant_id) DO UPDATE SET tenant_configuration_version_id=EXCLUDED.tenant_configuration_version_id,updated_at=clock_timestamp(); PERFORM app.append_audit('configuration.published','tenant_configuration_version',p_id); END; $$;
CREATE OR REPLACE FUNCTION app.create_rental_product(p_id uuid,p_cl uuid,p_code text,p_name text,p_description text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id(); BEGIN PERFORM app.require_staff_role('manager'); PERFORM 1 FROM app.category_location WHERE tenant_id=t AND category_location_id=p_cl FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND' USING ERRCODE='P0001'; END IF; INSERT INTO app.rental_product VALUES(t,p_id,p_cl,p_code,p_name,p_description,true,true,clock_timestamp()); PERFORM app.append_audit('catalog.product_created','rental_product',p_id); END; $$;
CREATE OR REPLACE FUNCTION app.update_product_rate(p_id uuid,p_product uuid,p_effective timestamptz,p_cents app.cents) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id(); v integer; BEGIN PERFORM app.require_staff_role('manager'); PERFORM 1 FROM app.rental_product WHERE tenant_id=t AND rental_product_id=p_product FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND' USING ERRCODE='P0001'; END IF; SELECT COALESCE(max(version_number),0)+1 INTO v FROM app.product_rate WHERE tenant_id=t AND rental_product_id=p_product; INSERT INTO app.product_rate VALUES(t,p_id,p_product,v,p_effective,p_cents,clock_timestamp()); PERFORM app.append_audit('catalog.product_rate_published','product_rate',p_id); END; $$;
CREATE OR REPLACE FUNCTION app.register_machine(p_id uuid,p_cl uuid,p_fleet text,p_name text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id(); BEGIN PERFORM app.require_staff_role('manager'); PERFORM 1 FROM app.category_location WHERE tenant_id=t AND category_location_id=p_cl; IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND' USING ERRCODE='P0001'; END IF; INSERT INTO app.machine(tenant_id,machine_id,category_location_id,display_name,operational_state,fleet_number) VALUES(t,p_id,p_cl,p_name,'in_service',p_fleet); PERFORM app.append_audit('fleet.machine_registered','machine',p_id); END; $$;
CREATE OR REPLACE FUNCTION app.initiate_machine_transfer(p_id uuid,p_machine uuid,p_to uuid,p_arrival timestamptz,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id(); m app.machine%ROWTYPE; s timestamptz:=clock_timestamp(); BEGIN PERFORM app.require_staff_role('manager'); SELECT * INTO m FROM app.machine WHERE tenant_id=t AND machine_id=p_machine FOR UPDATE; IF NOT FOUND OR m.operational_state<>'in_service' OR p_arrival<=s THEN RAISE EXCEPTION 'TRANSFER_NOT_INITIABLE' USING ERRCODE='P0001'; END IF; INSERT INTO app.machine_transfer(tenant_id,machine_transfer_id,machine_id,from_category_location_id,to_category_location_id,state,initiated_at,planned_arrival_at,reason,initiated_by_principal_id) VALUES(t,p_id,p_machine,m.category_location_id,p_to,'in_transit',s,p_arrival,p_reason,app.current_context_principal_id()); INSERT INTO app.machine_occupancy(tenant_id,machine_id,machine_transfer_id,occupancy_kind,blocking,occupancy_range) VALUES(t,p_machine,p_id,'transfer',true,tstzrange(s,p_arrival,'[)')); UPDATE app.machine SET operational_state='offline' WHERE tenant_id=t AND machine_id=p_machine; PERFORM app.append_audit('fleet.transfer_initiated','machine_transfer',p_id); END; $$;
CREATE OR REPLACE FUNCTION app.complete_machine_transfer(p_id uuid,p_completed timestamptz DEFAULT clock_timestamp()) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id(); x app.machine_transfer%ROWTYPE; BEGIN PERFORM app.require_staff_role('manager'); SELECT * INTO x FROM app.machine_transfer WHERE tenant_id=t AND machine_transfer_id=p_id FOR UPDATE; IF NOT FOUND OR x.state<>'in_transit' THEN RAISE EXCEPTION 'TRANSFER_NOT_COMPLETABLE' USING ERRCODE='P0001'; END IF; UPDATE app.machine_occupancy SET blocking=false WHERE tenant_id=t AND machine_transfer_id=p_id; UPDATE app.machine_transfer SET state='completed',completed_at=p_completed,completed_by_principal_id=app.current_context_principal_id() WHERE tenant_id=t AND machine_transfer_id=p_id; UPDATE app.machine SET category_location_id=x.to_category_location_id,operational_state='in_service' WHERE tenant_id=t AND machine_id=x.machine_id; PERFORM app.append_audit('fleet.transfer_completed','machine_transfer',p_id); END; $$;
CREATE OR REPLACE FUNCTION app.bind_device_to_machine(p_device uuid,p_machine uuid,p_at timestamptz) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id(); x app.device_installation%ROWTYPE; BEGIN PERFORM app.require_staff_role('manager'); PERFORM 1 FROM app.device WHERE tenant_id=t AND device_id=p_device AND active FOR UPDATE; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM app.machine WHERE tenant_id=t AND machine_id=p_machine) THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND' USING ERRCODE='P0001'; END IF; SELECT * INTO x FROM app.device_installation WHERE tenant_id=t AND device_id=p_device AND removed_at IS NULL FOR UPDATE; IF FOUND THEN IF p_at<=x.installed_at THEN RAISE EXCEPTION 'INVALID_DEVICE_INSTALLATION_TIME' USING ERRCODE='P0001'; END IF; UPDATE app.device_installation SET removed_at=p_at WHERE tenant_id=t AND device_installation_id=x.device_installation_id; END IF; INSERT INTO app.device_installation VALUES(t,gen_random_uuid(),p_device,p_machine,p_at,NULL,app.current_context_principal_id()); PERFORM app.append_audit('fleet.device_bound','device',p_device); END; $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['tenant_booking_policy','tenant_waiver_policy','tenant_inspection_policy','tenant_pricing_policy','tenant_payment_policy','tenant_telemetry_policy','tenant_sms_config','tenant_configuration_version','tenant_current_configuration','rental_product','product_rate','multi_day_discount_tier','addon','booking_rule','machine_state_change','machine_transfer','device_model','device','device_capability','device_installation','operating_limit','geofence'] LOOP EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY; ALTER TABLE app.%I FORCE ROW LEVEL SECURITY; CREATE POLICY tenant_context_policy ON app.%I USING (tenant_id=app.current_context_tenant_id() AND app.context_is_valid()) WITH CHECK (tenant_id=app.current_context_tenant_id() AND app.context_is_valid())',t,t,t); END LOOP; END; $$;
REVOKE ALL ON ALL TABLES IN SCHEMA app FROM talus_api,talus_customer,talus_staff,talus_device;
REVOKE ALL ON FUNCTION app.publish_configuration_version(uuid,integer,uuid,uuid,uuid,uuid,uuid,uuid,uuid),app.create_rental_product(uuid,uuid,text,text,text),app.update_product_rate(uuid,uuid,timestamptz,app.cents),app.register_machine(uuid,uuid,text,text),app.initiate_machine_transfer(uuid,uuid,uuid,timestamptz,text),app.complete_machine_transfer(uuid,timestamptz),app.bind_device_to_machine(uuid,uuid,timestamptz) FROM PUBLIC,talus_api,talus_customer,talus_staff,talus_device;
RESET ROLE;
